#include <vector>
#include <iostream>

int main() {
    std::vector<int> v1 = {1, 2, 4, 5};
    std::vector<int> v2 = {1, 2, 3, 9};
    std::vector<int> v3 = {1, 2};

    // v2 is less than v1 because 3 < 4 at index 2
    if (v2 < v1) { 
        std::cout << "v2 is lexicographically less than v1" << std::endl;
    }

    // v3 is less than v1 because v3 is a prefix of v1
    if (v3 < v1) {
        std::cout << "v3 is shorter and thus less than v1" << std::endl;
    }
}
